import { test, expect } from '@playwright/test';

test.describe('Footer Navigation Links', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should navigate to correct page when footer link is clicked', async ({ page }) => {
    // Verify footer is visible
    const footer = page.getByRole('region', { name: /footer/i });
    await expect(footer).toBeVisible();

    // Verify all footer links are present
    const navLinks = page.locator('[data-testid="footer-nav-link"]');
    await expect(navLinks).toHaveCount(5);

    // Verify home link is visible and has correct href
    const homeLink = page.getByRole('link', { name: /home/i });
    await expect(homeLink).toBeVisible();
    await expect(homeLink).toHaveAttribute('href', '/');

    // Verify about link is visible and has correct href
    const aboutLink = page.getByRole('link', { name: /about/i });
    await expect(aboutLink).toBeVisible();
    await expect(aboutLink).toHaveAttribute('href', '/about');

    // Verify contact link is visible and has correct href
    const contactLink = page.getByRole('link', { name: /contact/i });
    await expect(contactLink).toBeVisible();
    await expect(contactLink).toHaveAttribute('href', '/contact');

    // Verify services link is visible and has correct href
    const servicesLink = page.getByRole('link', { name: /services/i });
    await expect(servicesLink).toBeVisible();
    await expect(servicesLink).toHaveAttribute('href', '/services');

    // Verify pricing link is visible and has correct href
    const pricingLink = page.getByRole('link', { name: /pricing/i });
    await expect(pricingLink).toBeVisible();
    await expect(pricingLink).toHaveAttribute('href', '/pricing');

    // Verify contact link is visible and has correct href
    const contactLink = page.getByRole('link', { name: /contact/i });
    await expect(contactLink).toBeVisible();
    await expect(contactLink).toHaveAttribute('href', '/contact');

    // Click home link and verify navigation
    await homeLink.click();
    await expect(page).toHaveURL(/^\/home$/);

    // Click about link and verify navigation
    await aboutLink.click();
    await expect(page).toHaveURL(/^\/about$/);

    // Click contact link and verify navigation
    await contactLink.click();
    await expect(page).toHaveURL(/^\/contact$/);

    // Click services link and verify navigation
    await servicesLink.click();
    await expect(page).toHaveURL(/^\/services$/);

    // Click pricing link and verify navigation
    await pricingLink.click();
    await expect(page).toHaveURL(/^\/pricing$/);
  });

  test('should handle invalid footer links and display error message', async ({ page }) => {
    // Verify footer is visible
    const footer = page.getByRole('region', { name: /footer/i });
    await expect(footer).toBeVisible();

    // Verify all footer links are present
    const navLinks = page.locator('[data-testid="footer-nav-link"]');
    await expect(navLinks).toHaveCount(5);

    // Click invalid link (e.g., /invalid-page)
    const invalidLink = page.getByRole('link', { name: /invalid/i });
    await expect(invalidLink).toBeVisible();
    await invalidLink.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/page not found/i);
    await expect(errorMessage).toBeVisible();

    // Verify navigation is not redirected
    await expect(page).toHaveURL(/^\/invalid-page$/);
  });
});
